<script setup lang="ts">
import { onMounted, ref } from 'vue'
import { request, query, type Page } from '../api'
import { dateTime } from '../domain.js'
import Modal from './Modal.vue'
import StatusBadge from './StatusBadge.vue'
const rows=ref<any[]>([]),total=ref(0),page=ref(1),loading=ref(false),busy=ref(false),error=ref(''),success=ref(''),current=ref<any>(null),status=ref('fulfilled'),notes=ref('')
function snapshot(row:any){try{return typeof row.item_snapshot==='string'?JSON.parse(row.item_snapshot):row.item_snapshot||{}}catch{return{}}}
async function load(){loading.value=true;error.value='';try{const result=await request<Page>('/points-shop/redemptions'+query({page:page.value,page_size:10}));rows.value=result.items;total.value=result.total}catch(err){error.value=(err as Error).message}finally{loading.value=false}}
async function submit(){if(busy.value||!current.value)return;busy.value=true;error.value='';try{await request(`/points-shop/redemptions/${current.value.id}/review`,{method:'POST',body:JSON.stringify({status:status.value,notes:notes.value})});current.value=null;success.value='兑换处理结果已保存，驳回时积分和库存由服务端退回。';await load()}catch(err){error.value=(err as Error).message}finally{busy.value=false}}
onMounted(load)
</script>
<template><div class="page-heading"><div><h1>积分兑换履约</h1><p>实物交付后记录凭据，驳回待发放兑换时退回成长值与库存。</p></div><button class="button" @click="load">刷新记录</button></div><p v-if="error&&!current" class="notice danger" role="alert">{{ error }}</p><p v-if="success" class="notice success" role="status">{{ success }}</p><section class="panel"><div class="filter-bar"><span class="record-count">共 {{ total }} 条兑换记录</span></div><div class="table-scroll"><table><thead><tr><th>编号</th><th>用户</th><th>兑换商品</th><th>数量 / 成长值</th><th>状态</th><th>交付说明</th><th>时间</th><th>操作</th></tr></thead><tbody><tr v-if="loading"><td colspan="8" class="empty">正在加载…</td></tr><tr v-else-if="!rows.length"><td colspan="8" class="empty">暂无兑换记录</td></tr><tr v-for="row in rows" v-else :key="row.id"><td>#{{ row.id }}</td><td>#{{ row.user_id }}</td><td class="cell-title">{{ snapshot(row).title||'商品 #'+row.product_id }}</td><td>×{{ row.quantity }} / {{ row.points }}</td><td><StatusBadge :value="row.status" /></td><td>{{ row.notes||'—' }}</td><td>{{ dateTime(row.created_at) }}</td><td><button v-if="row.status==='pending_fulfillment'" class="text-button" @click="current=row;status='fulfilled';notes='';error=''">处理兑换</button><span v-else class="muted">已处理</span></td></tr></tbody></table></div><div class="pagination"><span>第 {{ page }} 页</span><button class="button small" :disabled="page<=1||loading" @click="page--;load()">上一页</button><button class="button small" :disabled="page*10>=total||loading" @click="page++;load()">下一页</button></div></section><Modal v-if="current" title="处理积分兑换" @close="!busy&&(current=null)"><form id="redemption-review" class="form-grid" @submit.prevent="submit"><p v-if="error" class="notice danger span-all" role="alert">{{ error }}</p><p class="notice span-all">{{ snapshot(current).title }} · 用户 #{{ current.user_id }} · {{ current.points }} 成长值</p><label class="span-all"><span>处理结果</span><select v-model="status"><option value="fulfilled">实物已交付</option><option value="rejected">驳回并退回积分库存</option></select></label><label class="span-all"><span>交付凭据或驳回说明 *</span><textarea v-model="notes" rows="4" maxlength="2000" required /></label></form><template #footer><button class="button" :disabled="busy" @click="current=null">取消</button><button class="button primary" form="redemption-review" :disabled="busy">{{ busy?'正在提交…':'保存处理结果' }}</button></template></Modal></template>
